1	package com.example.starter.translation.api;
2	
3	import com.fasterxml.jackson.annotation.JsonInclude;
4	import jakarta.validation.Valid;
5	import jakarta.validation.constraints.NotBlank;
6	import jakarta.validation.constraints.NotNull;
7	import jakarta.validation.constraints.Positive;
8	import jakarta.validation.constraints.PositiveOrZero;
9	import jakarta.validation.constraints.Size;
10	
11	import java.util.List;
12	
13	/**
14	 * 多语种段落发布 API 的请求与响应体。所有写操作均携带全局唯一 requestId。
15	 */
16	public final class ApiDtos {
17	
18	    private ApiDtos() {
19	    }
20	
21	    /** 初始段落输入。 */
22	    public record SegmentInput(
23	            @NotBlank(message = "segmentId 不能为空") @Size(max = 64) String segmentId,
24	            @NotBlank(message = "sourceText 不能为空") String sourceText) {
25	    }
26	
27	    /** 建文档请求：1~5 种目标语言，可携带初始段落。 */
28	    public record CreateDocumentRequest(
29	            @NotBlank(message = "requestId 不能为空") @Size(max = 128) String requestId,
30	            @NotNull(message = "targetLanguages 不能为空") @Size(min = 1, max = 5, message = "目标语言须为 1~5 种")
31	            List<@NotBlank(message = "语言码不能为空") String> targetLanguages,
32	            @NotNull(message = "segments 不能为空") List<@Valid SegmentInput> segments) {
33	    }
34	
35	    /** 增加段落请求。 */
36	    public record AddSegmentRequest(
37	            @NotBlank(message = "requestId 不能为空") @Size(max = 128) String requestId,
38	            @NotBlank(message = "segmentId 不能为空") @Size(max = 64) String segmentId,
39	            @NotBlank(message = "sourceText 不能为空") String sourceText) {
40	    }
41	
42	    /** 源文修订请求。 */
43	    public record ReviseSourceRequest(
44	            @NotBlank(message = "requestId 不能为空") @Size(max = 128) String requestId,
45	            @NotBlank(message = "sourceText 不能为空") String sourceText) {
46	    }
47	
48	    /** 译文提交请求；作者取 X-Actor-Id 请求头。 */
49	    public record SubmitTranslationRequest(
50	            @NotBlank(message = "requestId 不能为空") @Size(max = 128) String requestId,
51	            @NotBlank(message = "content 不能为空") String content,
52	            @Positive(message = "sourceVersion 必须为正数") int sourceVersion) {
53	    }
54	
55	    /** 译文批准请求；审核人取 X-Actor-Id 请求头。 */
56	    public record ApproveTranslationRequest(
57	            @NotBlank(message = "requestId 不能为空") @Size(max = 128) String requestId,
58	            @Positive(message = "translationVersion 必须为正数") int translationVersion) {
59	    }
60	
61	    /** 发布请求：携带期望的草稿与发布版本做乐观校验。 */
62	    public record PublishRequest(
63	            @NotBlank(message = "requestId 不能为空") @Size(max = 128) String requestId,
64	            @Positive(message = "expectedDraftVersion 必须为正数") int expectedDraftVersion,
65	            @PositiveOrZero(message = "expectedPublishedVersion 不能为负数") int expectedPublishedVersion) {
66	    }
67	
68	    /** 术语规则输入：sourceTerm 区分大小写，requiredTranslation 非空。 */
69	    public record TermRuleInput(
70	            @NotBlank(message = "sourceTerm 不能为空") @Size(max = 512) String sourceTerm,
71	            @NotBlank(message = "language 不能为空") String language,
